param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'serialization-info-missing-member-errors-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture



function Text($units){if($null -eq $units){return $null};return [string]::new([char[]]([int[]]$units))}
function Units($value){if($null -eq $value){return $null};return ,([int[]][char[]][string]$value)}
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json;$rows=[Collections.Generic.List[object]]::new();$nullInputControls=0
foreach($route in $plan.routes){for($index=0;$index -lt $plan.names.Count;$index++){$info=[Runtime.Serialization.SerializationInfo]::new([object],[Runtime.Serialization.FormatterConverter]::new());$info.AddValue('present',[object]'sentinel',[string]);$inputName=Text $plan.names[$index];if($route.StartsWith('GetValue:')){$types=[type[]]@([string],[type]);$arguments=[object[]]::new(2);$arguments[0]=$inputName;$arguments[1]=switch($route.Split(':')[1]){'null'{$null};'Object'{[object]};'String'{[string]};'Int32'{[int]}};$method=[Runtime.Serialization.SerializationInfo].GetMethod('GetValue',$types)}else{$arguments=[object[]]::new(1);$arguments[0]=$inputName;$method=[Runtime.Serialization.SerializationInfo].GetMethod($route,[type[]]@([string]))};if($null -eq $plan.names[$index]){if($null -ne $arguments[0]){throw 'Null name coerced'};$nullInputControls++};if($route -eq 'GetValue:null'){if($null -ne $arguments[1]){throw 'Null type coerced'};$nullInputControls++};try{$null=$method.Invoke($info,$arguments);throw 'Expected lookup failure'}catch{$errorValue=$_.Exception;while($null -ne $errorValue.InnerException){$errorValue=$errorValue.InnerException};if($errorValue -isnot [Runtime.Serialization.SerializationException] -and $errorValue -isnot [ArgumentNullException]){throw};$paramName=$null;if($errorValue -is [ArgumentException]){$paramName=$errorValue.ParamName};$rows.Add([ordered]@{route=$route;index=$index;exception=$errorValue.GetType().FullName;messageUnits=(Units $errorValue.Message);hResult=$errorValue.HResult;paramUnits=(Units $paramName);memberCount=$info.MemberCount;presentUnits=(Units $info.GetString('present'))})}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();nullInputControls=$nullInputControls;rows=$rows.ToArray();qualification=$plan.qualification};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 14 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS lookup errors: $($rows.Count) scenarios"
